import {sizePosition} from './risk-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function zeroPositionReason(result, r, fmt) {
  if (result.qty !== 0) return '';
  if (result.remaining === 0) return 'El presupuesto de pérdida del periodo está agotado. Revisa las pérdidas y el riesgo abierto registrados.';
  if (result.unitRisk > result.tradeBudget) return `Con entrada de ${r.entry} USD y stop de ${r.stop} USD, una acción arriesgaría ${fmt(result.unitRisk)}, por encima de tu límite disponible por operación de ${fmt(result.tradeBudget)}. Evalúa otra acción o una entrada menor que siga por encima del stop. Ajusta tu límite solo si coincide con tu capacidad de pérdida.`;
  if (result.unitCapital > result.available) return `Una acción con costos requiere ${fmt(result.unitCapital)} y tienes ${fmt(result.available)} de capital disponible. Evalúa una acción de menor precio.`;
  return `Una acción con costos requiere ${fmt(result.unitCapital)} y el límite de concentración permite ${fmt(result.positionLimit)}. Evalúa una acción de menor precio o revisa tu límite de concentración.`;
}
export function riskPanel(state,d){const r=state.risk||{},currency=state.profile.currency,fmt=n=>`${new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(n)} ${currency}`;const result=sizePosition(state.profile.capital,{...r,fx:currency==='USD'?1:r.fx});const fields=[['budget','¿Cuánto aceptas perder en total? ('+currency+')'],['perTrade','Pérdida planeada por operación ('+currency+')'],['realized','Pérdidas ya realizadas en el periodo ('+currency+')'],['openRisk','Pérdida al stop de posiciones abiertas ('+currency+')'],['invested','De este capital, ¿cuánto ya está comprometido? ('+currency+')'],['concentration','Máximo para esta nueva posición (% del capital)'],['entry','Precio de entrada por acción (USD)'],['stop','Stop propuesto por acción (USD)'],['cost','Costos totales estimados por acción, compra y venta (USD)'],...(currency==='USD'?[]:[['fx','Tipo de cambio: '+currency+' por 1 USD']])];return `<section class="card" id="risk-panel" style="margin:20px 0"><div class="eyebrow">GESTIÓN DE RIESGO · BOLSA</div><h2>¿Cuánto estás dispuesto a perder?</h2><p class="muted">Convierte tu tolerancia en un presupuesto monetario. Capital adicional declarado: <b>${fmt(state.profile.capital)}</b>. Tu reserva de emergencia queda fuera de este cálculo.</p><p class="chart-note">Tu tolerancia declarada: ${esc(state.profile.tolerance)}. No la convertimos automáticamente en un límite de pérdida definitivo. Confirma aquí el monto, el periodo y el límite por operación.</p><p class="chart-note" id="risk-draft-status">Tus cambios se guardan automáticamente como borrador. Los resultados corresponden a la última simulación confirmada.</p><form id="risk-form"><input type="hidden" name="_currency" value="${esc(currency)}"><div class="profile-fields"><label>Acción a evaluar (símbolo)<input name="symbol" value="${esc(r.symbol)}" placeholder="Por ejemplo, CAT" maxlength="12"></label><label>Periodo del presupuesto (por ejemplo, noviembre 2026)<input name="period" value="${esc(r.period)}" required maxlength="100"></label>${fields.map(([key,label])=>`<label>${label}<input type="number" name="${key}" value="${Number.isFinite(r[key])?r[key]:''}" min="${key==='concentration'?'0.01':'0'}" ${key==='concentration'?'max="100"':''} step="any" required>${key==='concentration'?'<small class="field-help">Escribe un porcentaje: 20 significa 20%, no un monto en dinero.</small>':key==='invested'?`<small class="field-help">De los ${fmt(state.profile.capital)} declarados. Usa 0 si aún no comprometiste ese capital; excluye inversiones anteriores.</small>`:''}</label>`).join('')}</div><p class="chart-note" style="margin-top:15px">Introduce datos vigentes del instrumento y del tipo de cambio. No se rellenan con los CSV históricos. Calculadora para una nueva posición en acciones compradas al contado, sin margen, opciones, venta en corto ni productos apalancados o inversos.</p><button class="primary">Guardar límites y simular posición ↗</button></form><div style="margin-top:20px" aria-live="polite">${!r.period?'<div class="notice">Pendiente: define tus límites. La app no presupone cuánto puedes perder.</div>':result.error?`<div class="notice">Revisa tu configuración: ${esc(result.error)}</div>`:`<div class="stats"><div class="stat"><div class="stat-label">Presupuesto de pérdida restante</div><strong>${fmt(result.remaining)}</strong><small>Total − pérdidas realizadas − riesgo abierto declarado</small></div><div class="stat"><div class="stat-label">Cantidad según tus límites</div><strong>${result.qty} acciones</strong><small>${result.qty===0?'Los límites no permiten una acción entera':'Se redondea hacia abajo; sin acciones fraccionadas'}</small></div><div class="stat"><div class="stat-label">Pérdida estimada al stop</div><strong>${fmt(result.estimatedLoss)}</strong><small>Incluye los costos estimados declarados</small></div></div>${result.qty===0?`<p class="notice">${zeroPositionReason(result,r,fmt)}</p>`:''}<p class="muted">Asignación con costos: <b>${fmt(result.allocation)}</b>. Pérdida por acción al stop: ${fmt(result.unitRisk)}. Pérdidas realizadas + riesgo abierto + simulación: ${fmt(result.totalPlannedRisk)} de ${fmt(r.budget)} para ${esc(r.period)}.</p>${result.remaining===0?'<div class="notice">Presupuesto agotado: no se dimensionan nuevas posiciones. Revisa tu estrategia; las ganancias no reponen automáticamente este presupuesto.</div>':''}${r.realized+r.openRisk>r.budget?'<div class="notice">Las pérdidas realizadas y el riesgo abierto ya superan el presupuesto. Actualiza tu evaluación antes de asumir más exposición.</div>':''}${r.budget/state.profile.capital*100>({ 'Hasta 5%':5,'Hasta 15%':15 }[state.profile.tolerance]??100)?'<div class="notice">El presupuesto supera el porcentaje de caída que declaraste tolerar. Revisa esta diferencia antes de usar la simulación.</div>':''}<div class="notice">${d.reasons.length?'Solo simulación: tu diagnóstico tiene prioridades pendientes. ':'Simulación, pendiente de evaluar la idoneidad del instrumento. '}La pérdida al stop no es un máximo garantizado. Si la acción pierde todo su valor, el capital expuesto en esta simulación sería ${fmt(result.fullLoss)}, incluidos los costos presupuestados.</div>`}</div><div class="side-foot"><b>Cómo se dimensiona:</b> acciones = parte entera del menor resultado entre presupuesto por operación ÷ pérdida por acción, capital disponible ÷ costo por acción y límite de concentración ÷ costo por acción. El presupuesto por operación también se limita al presupuesto total restante.<br>El stop puede ejecutarse a otro precio. No se modelan huecos de cotización, cambios de divisa, liquidez o correlación entre posiciones. El riesgo abierto y las pérdidas se actualizan manualmente; no hay conexión con tu bróker. Al agotarse el presupuesto de esta calculadora se detienen nuevas simulaciones, no las órdenes de una cuenta real.<br><a href="https://www.investor.gov/introduction-investing/investing-basics/glossary/stop-order" target="_blank" rel="noopener" class="text-button">Fuente: SEC · ejecución de órdenes stop ↗</a></div></section>`;}
export function bindRisk(state,onSave){const form=document.querySelector('#risk-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();form.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});const f=new FormData(form),r={period:String(f.get('period')||'').trim()};for(const [k,v] of f){if(k==='_currency')continue;if(k==='symbol'){r.symbol=String(v).trim().toUpperCase();}else if(k!=='period')r[k]=v===''?NaN:Number(v);}if(state.profile.currency==='USD')r.fx=1;r.currency=state.profile.currency;const result=sizePosition(state.profile.capital,r);if(result.error){document.querySelector('#risk-error')?.remove();const p=document.createElement('p');p.id='risk-error';p.className='notice';p.setAttribute('role','alert');p.textContent=result.error;form.append(p);if(result.field){const field=form.elements.namedItem(result.field);field.setAttribute("aria-invalid","true");field.setAttribute("aria-describedby","risk-error");field.focus();field.scrollIntoView({block:"center",behavior:"smooth"});}return;}onSave(r);};}

